import{_ as i,l as s,o as a,c as l,v as t,p as T,x as r,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"HTTP","description":"","frontmatter":{"title":"HTTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http.md","filePath":"cs/http.md","lastUpdated":1789023840000}'),p={name:"cs/http.md"};function h(E,e,P,_,f,m){const o=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><div class="epigraph"><p>HTTP 是无状态的请求—响应协议：方法、目标、头字段、可选正文；状态码告诉结果。</p><footer>—— 据 RFC 2616；Fielding 等, RFC 9110, HTTP Semantics, 2022 整理</footer></div><p><a href="/cs/dns-rr">上一课</a>把主机名变成 IP。传输层已能提供字节流或 QUIC 流。缺口是应用层：<strong>HTTP</strong>——对资源做 GET/POST 等，而不是把文档格式写进 TCP。本课用 RFC 9110 的语义，不把 TLS 记录写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每个网站自定「先发文件名再发长度」，浏览器无法通用。<a href="/cs/file-bytestream">字节流文件</a>在单机；跨机需要方法与媒体类型。HTTP：请求行（方法、目标）、头、正文；响应：状态码、头、正文。无状态：服务器默认不记上一请求，会话用 Cookie 等外挂。缺口是这套语义，不是拥塞算法。</p><p>HTTP/1.1 管道与队头、HTTP/2 多路复用点名；HTTP/3 跑在 <a href="/cs/quic-contrast">QUIC</a> 上。</p><p><span class="marginnote">幂等：GET 不应改资源。缓存与条件请求（<code>If-Modified-Since</code>）把<a href="/cs/buffer-dirty">缓冲</a>的思想拿到应用层，对象是表示而不是磁盘块。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端解析 URL：方案、主机、路径。DNS → 连接（TCP 80 或后课加密端口）→ 发请求 → 读响应。反向代理与网关仍讲 HTTP 语义。与 VFS 对照：都是「打开对象再读」，但 HTTP 对象是 URL，不是 inode，没有本地目录树的 POSIX 权限模型。</p>',9)),(a(),T(c,null,{default:r(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20URL%5B%22URL%22%5D%20--%3E%20DNS%5B%22%E8%A7%A3%E6%9E%90%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20DNS%20--%3E%20CONN%5B%22%E4%BC%A0%E8%BE%93%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20CONN%20--%3E%20REQ%5B%22%E8%AF%B7%E6%B1%82%E6%96%B9%E6%B3%95%E4%B8%8E%E5%A4%B4%22%5D%0A%20%20REQ%20--%3E%20RESP%5B%22%E7%8A%B6%E6%80%81%E7%A0%81%E4%B8%8E%E8%A1%A8%E7%A4%BA%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HTTP 把互联网的「文档与 API」统一成请求语义，让后课 CDN 可以缓存 GET。端到端：传输保证字节，HTTP 保证「这一表示的含义」；中间缓存必须遵守 Cache-Control，否则语义破。明文 HTTP 任何人可改方法与正文——这正是下一课要引入「需要一条有真实性的通道」的原因。</p><p>与进程：每个请求在服务器上最终变成某进程里的 <code>read</code>/<code>write</code>，经后课套接字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 REST 成熟度模型当协议标准。不引入 WebSocket 升级的全部状态。Cookie、CSRF 是安全课。明文的问题下一课只点到「为何要 TLS」，不讲握手。</p><p>内容协商（<code>Accept</code>）让同一 URL 返回不同表示。条件 GET 用验证器减少正文，边缓存与后课 CDN 都靠它。</p><p>后课默认：Web 语义是 HTTP。信道若无认证，中间人可改请求；下一课 TLS 入口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HTTP（RFC 9110 / 2616）是无状态请求—响应，方法加头加正文。</li><li>依赖 DNS 与传输；不内建加密。</li><li>真实性通道是下一课入口，完整握手在安全课。</li><li>出处：RFC 9110；RFC 2616；Fielding, <em>Architectural Styles…</em>（REST 论文，作语义背景）。</li></ul>',9))])}const C=i(p,[["render",h]]);export{A as __pageData,C as default};
